import java.io.*;import java.util.Scanner;
class CustomerRecord { int id;String name,address,mobile;CustomerRecord(int i,String n,String a,String m){id=i;name=n;address=a;mobile=m;} }
public class CustomerFileStorage { public static void main(String[] a){Scanner s=new Scanner(System.in);System.out.print("Number of customers: ");int n=s.nextInt();s.nextLine();CustomerRecord[] c=new CustomerRecord[n];for(int i=0;i<n;i++){System.out.print("ID: ");int id=s.nextInt();s.nextLine();System.out.print("Name: ");String name=s.nextLine();System.out.print("Address: ");String address=s.nextLine();System.out.print("Mobile: ");String mobile=s.nextLine();c[i]=new CustomerRecord(id,name,address,mobile);}try(DataOutputStream out=new DataOutputStream(new FileOutputStream("customers.dat"))){out.writeInt(n);for(CustomerRecord x:c){out.writeInt(x.id);out.writeUTF(x.name);out.writeUTF(x.address);out.writeUTF(x.mobile);}System.out.println("Saved to customers.dat");}catch(IOException e){System.out.println(e.getMessage());}s.close();} }
